#!/usr/bin/env python3
"""Lane thinorbit (S93).  2-adic image of the semigroup generated by the 8 unimodular blocks of order <= 4,
levels 2^1 .. 2^6 (hash-set breadth-first closure; a finite semigroup of invertible matrices is a group).
An open subgroup of SL_3(Z_2) grows by the factor 2^8 per level from some level on."""
import sys
import numpy as np
from group_probe import load

gens = load(sys.argv[1] if len(sys.argv) > 1 else "sub_k4_uni.txt")
kmax = int(sys.argv[2]) if len(sys.argv) > 2 else 4
prev = None
for k in range(1, kmax + 1):
    q = 1 << k
    G = np.array([g % q for g in gens], dtype=np.int64)
    w = (q ** np.arange(9, dtype=object))
    def codes(arr):
        a = arr.reshape(-1, 9)
        c = np.zeros(len(a), dtype=np.uint64)
        for i in range(9):
            c = c * np.uint64(q) + a[:, i].astype(np.uint64)
        return c
    front = G.copy()
    c = codes(front)
    c, idx = np.unique(c, return_index=True)
    front = front[idx]
    seen = c
    while len(front):
        prods = np.concatenate([np.einsum("nij,jk->nik", front, g) % q for g in G])
        c = codes(prods)
        c, idx = np.unique(c, return_index=True)
        prods = prods[idx]
        mask = ~np.isin(c, seen, assume_unique=True)
        front = prods[mask]
        seen = np.union1d(seen, c[mask])
        if len(seen) > 60_000_000:
            break
    print(f"mod 2^{k}: {len(seen)} elements" + (f"  (ratio to previous level {len(seen) / prev:.1f})" if prev else ""), flush=True)
    prev = len(seen)
